pub static UZ_META: LanguageMeta = LanguageMeta {
    code: "uz",
    name: "Uzbekcha",
    natively: "Uzbekcha",
    authors: &["TechnobladeUzb"],
};

/// Look up a locale by code (`en`, `pt-br`, …). Returns the
/// sorted (key, value) slice plus its metadata, or `None`.
pub fn locale(lang: &str) -> Option<(&'static [(&'static str, &'static str)], &'static LanguageMeta)> {
    match lang {
        "ar" => Some((AR, &AR_META)),
        "az" => Some((AZ, &AZ_META)),
        "bn" => Some((BN, &BN_META)),
        "cn" => Some((CN, &CN_META)),
        "en" => Some((EN, &EN_META)),
        "es" => Some((ES, &ES_META)),
        "fa" => Some((FA, &FA_META)),
        "fr" => Some((FR, &FR_META)),
        "gu" => Some((GU, &GU_META)),
        "hi" => Some((HI, &HI_META)),
        "id" => Some((ID, &ID_META)),
        "it" => Some((IT, &IT_META)),
        "jp" => Some((JP, &JP_META)),
        "ka" => Some((KA, &KA_META)),
        "ml" => Some((ML, &ML_META)),
        "mr" => Some((MR, &MR_META)),
        "ms" => Some((MS, &MS_META)),
        "or" => Some((OR, &OR_META)),
        "pt-br" => Some((PT_BR, &PT_BR_META)),
        "ru" => Some((RU, &RU_META)),
        "si" => Some((SI, &SI_META)),
        "ta" => Some((TA, &TA_META)),
        "tr" => Some((TR, &TR_META)),
        "uz" => Some((UZ, &UZ_META)),
        _ => None,
    }
}

/// All shipped language codes, in source order.
pub static LANGUAGES: &[&str] = &["ar", "az", "bn", "cn", "en", "es", "fa", "fr", "gu", "hi", "id", "it", "jp", "ka", "ml", "mr", "ms", "or", "pt-br", "ru", "si", "ta", "tr", "uz"];
